import { useState, useEffect } from "react";
import {fruits} from './data';
import "./App.css";

function App() {

  const [query, setQuery] = useState("");
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [selectedIndex, setSelectedIndex] = useState(-1);

  //debounce + search
  useEffect(() => {
    if(!query) {
      return;
    }

    const timer = setTimeout(() => {
      setLoading(true);
      setTimeout(() => {
        const result = fruits.filter((fruit: string) => {
          return fruit.toLowerCase().includes(query.toLowerCase());
        })
        setSuggestions(result);
        setLoading(false);
        setSelectedIndex(-1);
      }, 300);

    }, 300);

    return () => clearTimeout(timer);
  }, [query]);

  const handleKeydown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if(!suggestions) {
      return;
    }

    switch(e.key) {
      case 'ArrowDown':
        e.preventDefault();
        setSelectedIndex((prev) => {
          return prev === suggestions.length-1 ? 0 : prev + 1;
        });
        break;
      case 'ArrowUp':
        e.preventDefault();
        setSelectedIndex((prev) => {
          return prev <=0 ? suggestions.length-1 : prev-1;
        });
        break;
      case 'Enter':
        if(selectedIndex >=0) {
          setQuery(suggestions[selectedIndex]);
          setSuggestions([]);
          setSelectedIndex(-1);
        }
        break;
      case 'Escape':
        setQuery("");
        setSuggestions([]);
        break;
    }
  }

  const handleSelect = (value: string) => {
    setQuery(value);
    setSuggestions([]);
    setSelectedIndex(-1);
  }

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;

    setQuery(value);

    if(!value.trim()) {
      setSuggestions([]);
      setSelectedIndex(-1);
      setLoading(false);
    }
  }

  return (
    <div className="app">
      <h1>Autocomplete</h1>
      <div className="autocomplete">
        <input
          value={query}
          onChange={handleChange}
          onKeyDown={handleKeydown}
          placeholder="Search fruits"
          autoFocus
          >
        </input>

        {loading && (
          <div className="loading">
            loading...
          </div>
        )}

        {!loading && suggestions.length > 0 && (
          <ul className="suggestions">
            {suggestions.map((item, index) => {
              return <li key={item} 
                      className={selectedIndex === index ? "active" : ""} onClick={() => handleSelect(item)}>
                {item}
              </li>
            })}
          </ul>
        )}

        {!loading && query && suggestions.length === 0 && (
          <div className="no-results">
            No results found
          </div>
        )}

      </div>
    </div>
  )
}

export default App;

import { useState, useMemo, useEffect } from "react";
import type { User } from "./types/user";
import { getUsers } from "./services/userService";
import { SearchBar } from "./components/SearchBar";
import { Pagination } from "./components/Pagination";
import { DataTable } from "./components/DataTable";

import "./App.css";

const PAGE_SIZE = 5;

export default function App() {
  const [users, setUsers] = useState<User[]>([]);
  const [search, setSearch] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(false);
  const [error, SetError] = useState("");

  //Fetch data
  useEffect(() => {
    const loadUsers = async () => {
      try {
        setLoading(true);

        const users = await getUsers();
        setUsers(users);
      } catch (error) {
        SetError(
          error instanceof Error ? error.message : "Something went wrong",
        );
      } finally {
        setLoading(false);
      }
    };
    loadUsers();
  }, []);

  //Filtered users
  const filteredUsers = useMemo(() => {
    const query = search.trim().toLowerCase();

    if (!query) {
      return users;
    }

    return users.filter(
      (user) =>
        user.name.includes(query) ||
        user.email.includes(query) ||
        user.company.name.includes(query),
    );
  }, [search, users]);

  //Pagination
  const totalPages = Math.ceil(filteredUsers.length / PAGE_SIZE);
  const paginatedUsers = useMemo(() => {
    const start = (currentPage - 1) * PAGE_SIZE;

    return filteredUsers.slice(start, start + PAGE_SIZE);
  }, [currentPage, filteredUsers]);

  const handleSearch = (value: string) => {
    setSearch(value);
    setCurrentPage(1);
  };

  const handlePageChange = (page: number) => {
    setCurrentPage(page);
  };

  {
    loading && <div className="status">Loading...</div>;
  }

  {
    error && <div className="status error">{error}</div>;
  }

  return (
    <main className="container">
      <header>
        <h1>User management</h1>
        <span>Total users: {filteredUsers.length}</span>
      </header>
      <SearchBar value={search} onChange={handleSearch}></SearchBar>
      <DataTable users={paginatedUsers}></DataTable>
      {totalPages > 1 && (
        <Pagination
          currentPage={currentPage}
          totalPages={totalPages}
          onPageChange={handlePageChange}
        ></Pagination>
      )}
    </main>
  );
}

