setCounter(counter + 1);  // 0 + 1 = 1
setCounter(counter + 1);  // 0 + 1 = 1
// Result: counter = 1

// ✅ CORRECT - Uses previous state
setCounter(prev => prev + 1);  // 0 + 1 = 1
